    if (o.players.some((p) => JSON.stringify(copyEventData(p.victory)) !== p.victoryJson))
      return false;
  } catch {
    return false;
  }
  const size = Object.getOwnPropertyDescriptor(Map.prototype, "size")!.get!.call(o.hands);
