    policy: INITIAL_IDENTITY_POLICIES[o.kind],
    status: o.status,
    hands: hands.map((row, i) => ({ actorId: row.actorId, ...data[i]! })),
    reserve: data.slice(hands.length) as [InitialIdentityCard, InitialIdentityCard],
