}

/** 先核原可写字段，再消费与写 choice；model 的延迟读取夹在写槽与编码之间。 */
export function commitWildChildState(
  b: WildChildDataBinding,
  choice: NonNullable<WildChildReadState["choice"]>,
  model: () => NightLifeScope,
): boolean {
